{
  "url": "https://www.swsc-journal.org/articles/swsc/abs/2018/01/swsc170062/swsc170062.html",
  "prompt": "Give the citation (volume, article number, DOI) and the abstract."
}

{
  "command": "cd /tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad/lit1 && for doi in 10.1051/swsc/2018020 10.1029/91JA00155 10.1029/94GL01581; do curl -s \"https://api.crossref.org/works/$doi\" | python3 -I -c \"import json,sys; m=json.load(sys.stdin)['message']; print(m['DOI'], m.get('title'), m.get('container-title'), m.get('volume'), m.get('page'), m.get('article-number'), [a.get('family') for a in m.get('author',[])], m.get('issued'))\"; done",
  "description": "Get Crossref metadata for key DOIs"
}

